+.cmp-o span{display:block;font-size:12px;font-weight:800;color:var(--muted)}
+.cmp-o b{font-family:var(--font-num);font-size:30px;line-height:1.1}
+.cmp-o b i{font-style:normal;color:#A3ABBD;margin:0 8px;font-size:20px}
+.cmp-o em,.cmp-ch em{font-style:normal;font-family:var(--font-num);font-weight:800;font-size:13px;border-radius:999px;padding:2px 9px;margin-left:6px}
+.d-up{background:#E4F4EC;color:#1C6E49}.d-down{background:var(--rose-soft);color:#A2304A}.d-same,.d-na{background:#EEF1F6;color:#5A6580}
+.cmp-g{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
+.cmp-c{border:1px solid var(--line);border-radius:16px;padding:12px 14px;background:#fff}
+.cmp-ch{display:flex;align-items:center;gap:7px}
+.cmp-ch b{font-size:14px}.cmp-ch em{margin-left:auto}
+.cmp-n{display:flex;align-items:baseline;gap:6px;margin-top:8px;font-family:var(--font-num)}
+.cmp-n span{color:var(--muted);font-size:16px}.cmp-n i{font-style:normal;color:#A3ABBD}.cmp-n b{font-size:22px}
+.cmp-n small{margin-left:auto;font-family:var(--font-kr);font-size:11.5px;color:var(--muted);font-weight:700}
+.cmp-sp{width:100%;height:40px;margin-top:4px}
+.cmp-c p{margin:4px 0 0;font-size:12px;color:var(--muted)}
+.coach{margin-top:14px;border-radius:16px;padding:14px 18px;background:#F5F2FF;border:1px solid #DDD5FF}
+.coach-h{font-weight:800;font-size:14px;color:#3E2E8F;margin-bottom:6px}
+.coach ul{margin:0;padding:0;list-style:none;display:grid;gap:6px}
+.coach li{position:relative;padding-left:24px;font-size:14px;color:var(--ink-2);word-break:keep-all;line-height:1.65}
+.coach li::before{position:absolute;left:0;top:0;font-weight:900}
+.coach li.c-up::before{content:'▲';color:#1FA77A}.coach li.c-down::before{content:'▼';color:#D2486A}.coach li.c-same::before{content:'＝';color:#5A6580}.coach li.c-tip::before{content:'✦';color:#6A4FD8}
+@media (max-width:820px){.cmp-g{grid-template-columns:1fr 1fr}.cmp-o{text-align:left}.sb-r,.sb-sum{grid-template-columns:1fr 100px}}
 @media print{.ax{break-inside:avoid}.ax>summary::after{display:none}}
